%--------------------------------------------------------------------------
%sepByOptoStim
%By: Brielle Ferguson
%Date: 12/3/19
%Function that will take trial structure collected from the 
%readAnalayzePlotBehData function and then separate that into light on
%light off trials.
%Inputs: 
%   trials: data structure generated by function above
%Outputs: 
%   optoOff, optoOn: two separate trial structures separated into light on light off trials
%--------------------------------------------------------------------------

function [optoOff, optoOn] = sepByOptoStim(trials)
    for i = 1:length(trials)
        if contains(trials(i).opto, 'false')
            optoOff(i) = trials(i);
        end
        if contains(trials(i).opto, 'true')
            optoOn(i) = trials(i);
        end     
    end
  
 %delete empty elements in the array   
 optoOff = optoOff(find(arrayfun(@(optoOff) ~isempty(optoOff.number),optoOff)));
 optoOn = optoOn(find(arrayfun(@(optoOn) ~isempty(optoOn.number),optoOn)));
   
end

